sp_widget.client_script:
function($window, spModal) {
  var c = this;

  c.form = {
    score:    c.data.score      || '',
    comments: c.data.work_notes || ''
  };

  c.newNote   = '';
  c.saving    = false;
  c.addingNote = false;
  c.error     = '';

  // Helper: format file size
  c.formatSize = function(bytes) {
    if (!bytes) return '';
    var kb = (parseInt(bytes) / 1024).toFixed(2);
    return kb + ' KB';
  };

  // ── SUBMIT REVIEW ──
  c.submit = function() {
    if (!c.data.found) {
      c.error = 'No record found.';
      return;
    }
    c.saving = true;
    c.error  = '';

    c.data.action = 'submit_review';
    c.data.form   = angular.copy(c.form);

    c.server.update().then(function() {
      c.saving = false;
      if (c.data.success) {
        spModal.alert('✅ Review submitted successfully!').then(function() {
          // Stay on page in read-only mode — no redirect
          c.form.comments = '';
        });
      } else {
        c.error = c.data.error || 'An unexpected server error occurred.';
      }
    });
  };

  // ── ADD WORK NOTE ON SUBMITTED RECORD ──
  c.addNote = function() {
    if (!c.newNote || !c.newNote.trim()) return;

    c.addingNote = true;
    c.error      = '';

    c.data.action = 'add_note';
    c.data.form   = { comments: c.newNote };

    c.server.update().then(function() {
      c.addingNote = false;
      if (c.data.success) {
        c.newNote = '';
        spModal.alert('✅ Work note added successfully!');
      } else {
        c.error = c.data.error || 'Failed to add note.';
      }
    });
  };
}

sp_widget.css:
/* ══════════════════════════════════════
   BASE
══════════════════════════════════════ */
.grd-wrap {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  background: linear-gradient(135deg, #f0f4ff 0%, #fafafa 100%);
  min-height: 100vh;
  padding: 32px 24px;
  box-sizing: border-box;
}

/* ══════════════════════════════════════
   HEADER
══════════════════════════════════════ */
.grd-header { margin-bottom: 28px; }
.grd-header-left {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
}
.grd-task-chip {
  font-size: 22px;
  font-weight: 700;
  color: #1e293b;
  letter-spacing: -0.5px;
}
.grd-badge {
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.grd-badge-submitted {
  background: #f0fdf4;
  color: #15803d;
  border-color: #bbf7d0;
}

/* ══════════════════════════════════════
   SUBMITTED BANNER
══════════════════════════════════════ */
.grd-submitted-banner {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-radius: 12px;
  padding: 20px 24px;
  margin-bottom: 20px;
}
.grd-submitted-icon { font-size: 32px; line-height: 1; }
.grd-submitted-title {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 700;
  color: #15803d;
}
.grd-submitted-msg {
  margin: 0;
  font-size: 13px;
  color: #166534;
  line-height: 1.5;
}

/* ══════════════════════════════════════
   CARDS
══════════════════════════════════════ */
.grd-card {
  background: #ffffff;
  border-radius: 12px;
  border: 1px solid #e2e8f0;
  padding: 24px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  transition: box-shadow 0.2s;
  margin-bottom: 20px;
}
.grd-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.08); }
.grd-card-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid #f1f5f9;
}
.grd-card-icon { font-size: 18px; }
.grd-card-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: #1e293b;
}

/* ══════════════════════════════════════
   PROGRAM CARD
══════════════════════════════════════ */
.grd-program-card { margin-bottom: 20px; }
.grd-program-header {
  background: linear-gradient(135deg, #065f46, #10b981);
  margin: -24px -24px 20px;
  padding: 16px 24px;
  border-radius: 11px 11px 0 0;
  border-bottom: none;
}
.grd-program-header .grd-card-title,
.grd-program-header .grd-card-icon { color: #fff; }
.grd-program-desc {
  border-top: 1px solid #e2e8f0;
  padding-top: 16px;
  margin-top: 4px;
}
.grd-desc-text {
  margin: 6px 0 0;
  font-size: 13px;
  color: #475569;
  line-height: 1.6;
}

/* ══════════════════════════════════════
   APPLICANT CARD
══════════════════════════════════════ */
.grd-applicant-card { margin-bottom: 20px; }
.grd-applicant-header {
  background: linear-gradient(135deg, #1e40af, #3b82f6);
  margin: -24px -24px 20px;
  padding: 16px 24px;
  border-radius: 11px 11px 0 0;
  border-bottom: none;
}
.grd-applicant-header .grd-card-title,
.grd-applicant-header .grd-card-icon { color: #fff; }

/* ══════════════════════════════════════
   INFO GRID
══════════════════════════════════════ */
.grd-applicant-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 20px;
}
.grd-info-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.grd-info-label {
  font-size: 11px;
  font-weight: 600;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.grd-info-value {
  font-size: 14px;
  color: #1e293b;
  font-weight: 500;
}
.grd-info-badge {
  display: inline-block;
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
  border-radius: 6px;
  padding: 2px 10px;
  font-size: 13px;
  font-weight: 600;
  width: fit-content;
}
.grd-info-link { color: #2563eb; text-decoration: none; }
.grd-info-link:hover { text-decoration: underline; }

/* ══════════════════════════════════════
   DOCUMENTS
══════════════════════════════════════ */
.grd-docs-section {
  border-top: 1px solid #e2e8f0;
  padding-top: 16px;
}
.grd-docs-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  color: #475569;
  margin-bottom: 12px;
}
.grd-doc-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  margin-bottom: 8px;
  transition: box-shadow 0.2s;
}
.grd-doc-item:hover { box-shadow: 0 2px 8px rgba(0,0,0,0.06); }
.grd-doc-left { display: flex; align-items: center; gap: 10px; }
.grd-doc-icon { font-size: 22px; }
.grd-doc-name {
  margin: 0;
  font-size: 13px;
  font-weight: 500;
  color: #1e293b;
}
.grd-doc-size { margin: 0; font-size: 11px; color: #94a3b8; }
.grd-doc-download {
  font-size: 18px;
  color: #3b82f6;
  text-decoration: none;
  padding: 4px 8px;
  border-radius: 6px;
  transition: background 0.2s;
}
.grd-doc-download:hover { background: #eff6ff; }

/* ══════════════════════════════════════
   TWO COLUMN GRID
══════════════════════════════════════ */
.grd-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 20px;
}

/* ══════════════════════════════════════
   FORM FIELDS
══════════════════════════════════════ */
.grd-field { margin-bottom: 18px; }
.grd-label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: #475569;
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.req { color: #ef4444; }
.grd-input {
  width: 100%;
  padding: 9px 12px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  font-size: 13px;
  color: #1e293b;
  background: #f8fafc;
  transition: border-color 0.2s, box-shadow 0.2s;
  box-sizing: border-box;
  outline: none;
  -webkit-appearance: none;
}
.grd-input:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99,102,241,0.12);
  background: #fff;
}
.grd-textarea { resize: vertical; min-height: 100px; }
.grd-char-hint {
  text-align: right;
  font-size: 11px;
  color: #94a3b8;
  margin: 4px 0 0;
}

/* ══════════════════════════════════════
   SCORE BUTTONS
══════════════════════════════════════ */
.grd-score-wrap { margin-bottom: 8px; }
.grd-score-buttons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 10px 0;
}
.grd-score-btn {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  border: 2px solid #e2e8f0;
  background: #f8fafc;
  font-size: 14px;
  font-weight: 600;
  color: #64748b;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}
.grd-score-btn:hover {
  border-color: #6366f1;
  color: #6366f1;
  background: #eef2ff;
  transform: translateY(-2px);
}
.score-active.score-low  { background: #fef2f2; border-color: #ef4444; color: #ef4444; }
.score-active.score-mid  { background: #fffbeb; border-color: #f59e0b; color: #f59e0b; }
.score-active.score-high { background: #f0fdf4; border-color: #22c55e; color: #22c55e; }
.grd-score-hint {
  font-size: 12px;
  color: #64748b;
  margin: 6px 0 0;
}

/* ══════════════════════════════════════
   SCORE BAR
══════════════════════════════════════ */
.score-bar-wrap {
  height: 6px;
  background: #e2e8f0;
  border-radius: 999px;
  overflow: hidden;
  margin-top: 10px;
}
.score-bar {
  height: 100%;
  border-radius: 999px;
  transition: width 0.4s ease, background 0.4s ease;
}

/* ══════════════════════════════════════
   SCORE DISPLAY (READONLY)
══════════════════════════════════════ */
.grd-score-display {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin: 8px 0 10px;
}
.grd-score-number {
  font-size: 40px;
  font-weight: 700;
  color: #1e293b;
  line-height: 1;
}
.grd-score-denom {
  font-size: 16px;
  color: #94a3b8;
  font-weight: 500;
}

/* ══════════════════════════════════════
   WORK NOTES INPUT
══════════════════════════════════════ */
.grd-note-input-wrap { margin-bottom: 16px; }
.grd-note-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 6px;
}

/* ══════════════════════════════════════
   ACTIVITY STREAM
══════════════════════════════════════ */
.grd-activity-stream {
  border-top: 1px solid #e2e8f0;
  padding-top: 14px;
  max-height: 320px;
  overflow-y: auto;
}
.grd-activity-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 12px;
}
.grd-activity-item {
  display: flex;
  gap: 10px;
  margin-bottom: 14px;
}
.grd-activity-avatar {
  width: 34px;
  height: 34px;
  min-width: 34px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #4f46e5);
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}
.grd-activity-body {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 10px 14px;
  flex: 1;
}
.grd-activity-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}
.grd-activity-user {
  font-size: 12px;
  font-weight: 600;
  color: #1e293b;
}
.grd-activity-time {
  font-size: 11px;
  color: #94a3b8;
}
.grd-activity-text {
  margin: 0;
  font-size: 13px;
  color: #475569;
  line-height: 1.5;
  white-space: pre-wrap;
}
.grd-activity-empty {
  text-align: center;
  font-size: 13px;
  color: #94a3b8;
  padding: 20px 0;
  border-top: 1px solid #e2e8f0;
  margin-top: 8px;
}

/* ══════════════════════════════════════
   READONLY FIELD
══════════════════════════════════════ */
.grd-readonly {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 9px 12px;
  font-size: 13px;
  color: #475569;
  display: flex;
  align-items: center;
  gap: 6px;
}
.grd-readonly-icon { font-size: 14px; }

/* ══════════════════════════════════════
   ALERTS
══════════════════════════════════════ */
.grd-alert {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  border-radius: 8px;
  font-size: 13px;
  margin-bottom: 16px;
}
.grd-alert-danger {
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #dc2626;
}

/* ══════════════════════════════════════
   BUTTONS
══════════════════════════════════════ */
.grd-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  padding-top: 8px;
}
.grd-btn {
  padding: 10px 22px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s;
}
.grd-btn-sm {
  padding: 6px 14px;
  font-size: 12px;
}
.grd-btn-ghost {
  background: #fff;
  border: 1px solid #e2e8f0;
  color: #475569;
}
.grd-btn-ghost:hover { background: #f1f5f9; }
.grd-btn-primary {
  background: linear-gradient(135deg, #6366f1, #4f46e5);
  color: #fff;
  box-shadow: 0 2px 8px rgba(99,102,241,0.35);
}
.grd-btn-primary:hover:not([disabled]) {
  background: linear-gradient(135deg, #4f46e5, #4338ca);
  box-shadow: 0 4px 14px rgba(99,102,241,0.45);
  transform: translateY(-1px);
}
.grd-btn-primary[disabled] {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

/* ══════════════════════════════════════
   RESPONSIVE
══════════════════════════════════════ */
@media (max-width: 768px) {
  .grd-wrap { padding: 20px 16px; }
  .grd-grid { grid-template-columns: 1fr; }
  .grd-applicant-grid { grid-template-columns: 1fr; }
  .grd-actions { flex-direction: column; }
  .grd-btn { justify-content: center; }
  .grd-score-buttons { gap: 6px; }
  .grd-score-btn { width: 34px; height: 34px; font-size: 12px; }
  .grd-note-actions { flex-direction: column; align-items: flex-end; gap: 6px; }
}

sp_widget.script:
(function() {
  data.found     = false;
  data.success   = false;
  data.error     = '';
  data.submitted = false;

  var userId = gs.getUserID();

  var groups = [];
  var grMem = new GlideRecord('sys_user_grmember');
  grMem.addQuery('user', userId);
  grMem.query();
  while (grMem.next()) {
    groups.push(grMem.getValue('group'));
  }

  var sysId = $sp.getParameter('sys_id');
  if (!sysId) return;

  var gr = new GlideRecord('x_enno_gatenow_grant_review');
  if (!gr.get(sysId)) return;

  if (groups.indexOf(gr.getValue('assignment_group')) === -1) return;

  // ── HANDLE ADD WORK NOTE ──
  if (input && input.action === 'add_note' && input.form) {
    if (input.form.comments) {
      gr.work_notes = input.form.comments;
      gr.update();
    }
    data.found     = true;
    data.success   = true;
    data.submitted = true;
  }

  // ── HANDLE SUBMIT ──
  if (input && input.action === 'submit_review' && input.form) {
    var f = input.form;
    if (f.score)    gr.setValue('score', parseInt(f.score, 10));
    if (f.comments) gr.work_notes = f.comments;
    gr.setValue('reviewer', userId);
    gr.setValue('status', 'Submitted');
    gr.update();

    data.found     = true;
    data.success   = true;
    data.submitted = true;
  }

  // ── CHECK STATUS ──
  var currentStatus = (gr.getValue('status') || '').toString().toLowerCase().trim();
  if (currentStatus === 'submitted' || currentStatus === 'review completed') {
    data.submitted = true;
  }

  // ── LOAD APPLICANT INFO ──
    // ── LOAD APPLICANT INFO ──
  var applicantSysId = gr.getValue('applicant');
  var applicant = {};
  if (applicantSysId) {
    var appGr = new GlideRecord('x_enno_gatenow_service_applicants');
    if (appGr.get(applicantSysId)) {

      // Basic Info
      applicant.number          = appGr.getValue('number')                      || '';
      applicant.first_name      = appGr.getValue('first_name')                   || '';
      applicant.middle_name     = appGr.getValue('middle_name')                  || '';
      applicant.last_name       = appGr.getValue('last_name')                    || '';
      applicant.email           = appGr.getValue('email')                       || '';
      applicant.phone           = appGr.getValue('phone_number')                || '';
      applicant.gender          = appGr.getDisplayValue('gender')               || '';
      applicant.dob             = appGr.getDisplayValue('birthdate')            || '';
      applicant.marital_status  = appGr.getDisplayValue('marital_status')       || '';
      applicant.race            = appGr.getDisplayValue('race')                 || '';
      applicant.ethnicity       = appGr.getDisplayValue('ethnicity')            || '';
      applicant.education       = appGr.getDisplayValue('education_level')      || '';
      applicant.military_status = appGr.getDisplayValue('military_status')      || '';
      applicant.applicant_type  = appGr.getDisplayValue('applicant_type')       || '';
      applicant.tribal          = appGr.getDisplayValue('tribal_affiliation')   || '';
      applicant.citizenship     = appGr.getDisplayValue('citizenship_status')   || '';
      applicant.identity_type   = appGr.getDisplayValue('identity_type')        || '';
      applicant.disability      = appGr.getDisplayValue('disability_status')    || '';
      applicant.ssn             = appGr.getValue('ssn')                         || '';
      applicant.tin             = appGr.getValue('tin_ein')                     || '';
      applicant.uei             = appGr.getValue('uei')                         || '';
      applicant.street          = appGr.getValue('street')                      || '';
      applicant.city            = appGr.getValue('city')                        || '';
      applicant.country         = appGr.getValue('country')                     || '';
      applicant.zip             = appGr.getValue('zip_postal_code')             || '';

      // Proposal Info
      applicant.organization        = appGr.getValue('organization')                || '';
      applicant.program_category    = appGr.getDisplayValue('program_category')     || '';
      applicant.requested_budget    = appGr.getDisplayValue('requested_budget')     || '';
      applicant.short_desc          = appGr.getValue('short_description')           || '';
      applicant.proposal_desc       = appGr.getValue('proposal_description')        || '';
      applicant.goals               = appGr.getValue('project_goals_and_objectives')|| '';
      applicant.methodology         = appGr.getValue('project_activities_methodology')|| '';
      applicant.project_start       = appGr.getDisplayValue('project_start_date')   || '';
      applicant.project_end         = appGr.getDisplayValue('project_end_date')     || '';
      applicant.submission_date     = appGr.getDisplayValue('submission_date')      || '';
      applicant.state               = appGr.getDisplayValue('state')                || '';



      // ✅ Applicant Attachments — GlideRecord query only, no GlideSysAttachment
      var appDocs = [];
      var appAttGr = new GlideRecord('sys_attachment');
      appAttGr.addQuery('table_name', 'x_enno_gatenow_service_applicants');
      appAttGr.addQuery('table_sys_id', appGr.getUniqueValue());
      appAttGr.query();
      while (appAttGr.next()) {
        appDocs.push({
          name:   appAttGr.getValue('file_name'),
          size:   appAttGr.getValue('size_bytes'),
          sys_id: appAttGr.getValue('sys_id'),
          url:    '/sys_attachment.do?sys_id=' + appAttGr.getValue('sys_id')
        });
      }
      applicant.documents = appDocs;
    }
  }

  // ── LOAD PROGRAM INFO ──
    // ── LOAD PROGRAM INFO ──
  var programSysId = gr.getValue('program');
  var program = {};
  if (programSysId) {
    var progGr = new GlideRecord('x_enno_gatenow_grant_program');
    if (progGr.get(programSysId)) {
      program.name               = progGr.getDisplayValue('program_name')               || '';
      program.number             = progGr.getValue('number')                    || '';
      program.start_date         = progGr.getDisplayValue('start_date')         || '';
			program.category           = progGr.getDisplayValue('category') || '';
      program.end_date           = progGr.getDisplayValue('end_date')           || '';
      program.status             = progGr.getDisplayValue('status')             || '';
      program.budget             = progGr.getDisplayValue('program_budget')             || '';
      program.description        = progGr.getValue('program_description')       || '';
      program.synopsis           = progGr.getValue('synopsis')                  || '';
      program.terms              = progGr.getValue('terms_and_conditions')      || '';
      program.eligibility        = progGr.getValue('eligibility_summary')       || '';
      program.summary_statement  = progGr.getValue('summary_statement')         || '';



      // ✅ Program Attachments — GlideRecord query only, no GlideSysAttachment
      var progDocs = [];
      var progAttGr = new GlideRecord('sys_attachment');
      progAttGr.addQuery('table_name', 'x_enno_gatenow_grant_program');
      progAttGr.addQuery('table_sys_id', progGr.getUniqueValue());
      progAttGr.query();
      while (progAttGr.next()) {
        progDocs.push({
          name:   progAttGr.getValue('file_name'),
          size:   progAttGr.getValue('size_bytes'),
          sys_id: progAttGr.getValue('sys_id'),
          url:    '/sys_attachment.do?sys_id=' + progAttGr.getValue('sys_id')
        });
      }
      program.documents = progDocs;
    }
  }

  // ── LOAD WORK NOTES ACTIVITY STREAM ──
  var workNotesList = [];
  var jrnlGr = new GlideRecord('sys_journal_field');
  jrnlGr.addQuery('name', 'x_enno_gatenow_grant_review');
  jrnlGr.addQuery('element', 'work_notes');
  jrnlGr.addQuery('element_id', gr.getUniqueValue());
  jrnlGr.orderByDesc('sys_created_on');
  jrnlGr.query();
  while (jrnlGr.next()) {
    workNotesList.push({
      value:   jrnlGr.getValue('value'),
      created: jrnlGr.getDisplayValue('sys_created_on'),
      user:    jrnlGr.getDisplayValue('sys_created_by')
    });
  }

  // ── LOAD FORM DATA ──
  data.found            = true;
  data.sys_id           = gr.getUniqueValue();
  data.number           = gr.getValue('number');
  data.assignment_group = gr.getDisplayValue('assignment_group');
  data.status           = gr.getDisplayValue('status');
  data.score            = gr.getValue('score');
  data.work_notes       = gr.getValue('work_notes') || '';
  data.work_notes_list  = workNotesList;
  data.applicant        = applicant;
  data.program          = program;
})();
